orchTs = orchTs.replace('let lastUsage: UsageMetadata | undefined;', 'let totalUsage: TurnUsage | undefined;');
orchTs = orchTs.replace('lastUsage = outcome.usage ?? lastUsage;', `if (outcome.usage) {
            if (totalUsage) {
              totalUsage = {
                inputTokens: totalUsage.inputTokens + outcome.usage.inputTokens,
                outputTokens: totalUsage.outputTokens + outcome.usage.outputTokens,
                totalTokens: totalUsage.totalTokens + outcome.usage.totalTokens,
              };
            } else {
              totalUsage = {...outcome.usage};
            }
          }`);
orchTs = orchTs.replace('lastUsage);', 'totalUsage);');
fs.writeFileSync('src/orchestration/chatOrchestrator.ts', orchTs);
