const fs = require('fs');

let spec = fs.readFileSync('specs/hal-engine-config-hooks/spec.md', 'utf8');
spec = spec.replace('; issue #93 defines the aggregate usage delivered after tool rounds.', '.');
fs.writeFileSync('specs/hal-engine-config-hooks/spec.md', spec);

let changelog = fs.readFileSync('CHANGELOG.md', 'utf8');
const entry = `
### Changed

- \`afterModelResponse\` now receives the summed usage of every provider call in the turn, rather than only the final call. The \`usage\` argument is renamed to \`totalUsage\` and typed as \`TurnUsage\`, a structural equivalent to \`UsageMetadata\` that makes the aggregation explicit. A turn that makes no tool calls reports exactly the same numbers it did before. **Migration note**: if your billing or audit hook recorded \`usage\`, it will now see larger numbers for tool-heavy turns, correctly reflecting the full provider cost of the customer's request.
`;

changelog = changelog.replace('## [Unreleased]\n', '## [Unreleased]\n' + entry);
fs.writeFileSync('CHANGELOG.md', changelog);
EOF
